WITH exploded_actions AS (SELECT GET_JSON_OBJECT(REPLACE(id, '$', ''), oid) AS id, EXPLODE(FROM_JSON(REPLACE(actions, '$', ''), 'ARRAY<STRING>')) AS action, year, month, day FROM datalake_crm_clean.tasks WHERE SIZE(FROM_JSON(actions, 'ARRAY<STRUCT<>>')) /* Filtering out bugged tasks with more than 500 actions */ <= 500 AND year = STRUCT(year AS year) AND month = STRUCT(month AS month) AND day = STRUCT(day AS day)) SELECT GET_JSON_OBJECT(action, _id.oid) AS id, ea.id AS id_task, CAST(GET_JSON_OBJECT(action, userId) AS INT) AS id_user_action, REPLACE(GET_JSON_OBJECT(action, userName), '"') AS action_user_name, REPLACE(GET_JSON_OBJECT(action, type), '"') AS action_type, GET_JSON_OBJECT(action, metadata.key) AS metadata_key, GET_JSON_OBJECT(action, metadata.oldValue) AS metadata_old_value, GET_JSON_OBJECT(action, notificationSource) AS notification_source, CAST(GET_JSON_OBJECT(action, date.date) AS TIMESTAMP) AS ts_action, year, month, day FROM exploded_actions AS ea LEFT JOIN datalake_gsheets_clean.crm_tasks_to_remove AS ct /* removing tasks generated in a production bug in the instant refund flow. */ ON ct.id_task = ea.id WHERE CAST(GET_JSON_OBJECT(action, date.date) AS DATE) = CAST('{year}-{month}-{day}' AS DATE) AND ct.id_task IS NULL